-- Delete call-related data
DELETE FROM call_transcripts;
DELETE FROM call_recordings;
DELETE FROM callAnalytics;
DELETE FROM callRouting;
DELETE FROM callLogs;
DELETE FROM callDraftTickets;

-- Delete ticket-related data
DELETE FROM ticketKbSuggestions;
DELETE FROM ticketSurveys;
DELETE FROM ticketMerges;
DELETE FROM ticketActivity;
DELETE FROM ticketNotes;
DELETE FROM ticketFeedback;
DELETE FROM ticketReplies;
DELETE FROM tickets;

-- Verify deletion
SELECT 
  (SELECT COUNT(*) FROM callLogs) as remaining_callLogs,
  (SELECT COUNT(*) FROM callDraftTickets) as remaining_drafts,
  (SELECT COUNT(*) FROM tickets) as remaining_tickets,
  (SELECT COUNT(*) FROM ticketReplies) as remaining_replies;

